/// The header's choice of a `size_t` format for the target: C99's `z` modifier, `c99`, except
/// on Windows, whose compilers the header names (`_MSC_VER`, `__MINGW32__`), where it is
/// Microsoft's `I64` modifier, `msvc_64`, if `size_t` is as wide as `unsigned long long`, 64
/// bits, and its `I` modifier, `msvc`, if not.
const fn size_format(
    c99: &'static str,
    msvc_64: &'static str,
    msvc: &'static str,
) -> &'static str {
    if !cfg!(windows) {
        c99
    } else if cfg!(target_pointer_width = "64") {
        msvc_64
    } else {
        msvc
    }
}

